var t = Date.now() / 1000;

var pression_hp = 5 + Math.sin(t/30) * 1.5 + (Math.random()-0.5)*0.3;
var debit_feed = 15 + Math.sin(t/20) * 3 + (Math.random()-0.5)*0.5;
var salinite = 350 + Math.sin(t/60) * 50 + (Math.random()-0.5)*20;
var niveau = 60 + Math.sin(t/45) * 15 + (Math.random()-0.5)*2;
var temperature = 26 + Math.sin(t/120) * 2 + (Math.random()-0.5)*0.3;

msg.payload = {
    pression_hp: parseFloat(pression_hp.toFixed(2)),
    debit_feed: parseFloat(debit_feed.toFixed(2)),
    salinite: parseFloat(salinite.toFixed(1)),
    niveau: parseFloat(niveau.toFixed(1)),
    temperature: parseFloat(temperature.toFixed(1)),
    rendement: parseFloat((debit_feed/20*100).toFixed(1))
};
return msg;

// Format payload for MQTT
msg.payload = JSON.stringify(msg.payload);
msg.topic = "v1/devices/me/telemetry";
return msg;

var data = msg.payload;
var alarmes = [];
var niveau = "NORMAL";
var etat = "STOPPING";

// Check alarm conditions
if (data.pression_hp > 60) {
    alarmes.push({ type: "PRESSION_HP", valeur: data.pression_hp, seuil: 60 });
    niveau = "WARNING";
}
if (data.debit_feed < 2) {
    alarmes.push({ type: "DEBIT_FAIBLE", valeur: data.debit_feed, seuil: 2 });
    niveau = "CRITICAL";
}
if (data.temperature > 35) {
    alarmes.push({ type: "SURCHAUFFE", valeur: data.temperature, seuil: 35 });
    niveau = "WARNING";
}
if (data.salinite > 380) {
    alarmes.push({ type: "SALINITE_HAUTE", valeur: data.salinite, seuil: 380 });
    niveau = "WARNING";
}

if (alarmes.length === 0) {
    etat = "STOPPING";
} else {
    etat = "ALARME";
}

msg.payload = {
    niveau: niveau,
    count: alarmes.length,
    details: alarmes,
    etat: etat,
    timestamp: new Date().toTimeString().slice(0,8)
};

return msg;

// Split payload into individual MQTT topics
var data = msg.payload;
var messages = [];

Object.keys(data).forEach(function(key) {
    messages.push({
        payload: String(data[key]),
        topic: "capteurs/" + key
    });
});

return [messages];

// Process web command
var cmd = msg.payload;
var response = {};

if (cmd.command === "START") {
    response = { status: "OK", action: "STARTED", timestamp: Date.now() };
} else if (cmd.command === "STOP") {
    response = { status: "OK", action: "STOPPED", timestamp: Date.now() };
} else {
    response = { status: "ERROR", message: "Unknown command", timestamp: Date.now() };
}

msg.payload = response;
return msg;

// Simulate sensor values with variation
var pression_hp = +(Math.random() * 5).toFixed(1);
var debit_feed  = +(Math.random() * 15).toFixed(1);
var salinite    = +(750 + Math.random() * 100).toFixed(0);
var niveau      = +(48 + Math.random() * 10).toFixed(1);
var temperature = +(27 + Math.random() * 2).toFixed(2);

msg.payload = {
    pression_hp: pression_hp,
    debit_feed:  debit_feed,
    salinite:    salinite,
    niveau:      niveau,
    temperature: temperature
};

return msg;

var d = msg.payload;
var alarmes = [];
var niveau_alerte = "NORMAL";
var etat = "NORMAL";

// Alarm thresholds
if (d.salinite > 600) {
    alarmes.push("🔴 CRITIQUE: Salinité = " + d.salinite + " ppm (>600)");
    niveau_alerte = "CRITICAL";
    etat = "STARTING";
}
if (d.pression_hp > 60) {
    alarmes.push("⚠️ WARNING: Pression HP = " + d.pression_hp + " bar (>60)");
    if (niveau_alerte !== "CRITICAL") niveau_alerte = "WARNING";
}
if (d.debit_feed < 2) {
    alarmes.push("⚠️ WARNING: Débit faible = " + d.debit_feed + " m³/h (<2)");
    if (niveau_alerte !== "CRITICAL") niveau_alerte = "WARNING";
}
if (d.temperature > 35) {
    alarmes.push("⚠️ WARNING: Température = " + d.temperature + " °C (>35)");
    if (niveau_alerte !== "CRITICAL") niveau_alerte = "WARNING";
}

// Log alarm details to context
node.warn(alarmes.length + " alarme(s): " + alarmes.join(" | "));

var texte = "";
if (alarmes.length === 0) {
    texte = "✅ Système nominal\n";
    texte += "💧 Salinité: " + d.salinite + " ppm\n";
    texte += "📊 Débit: " + d.debit_feed + " m³/h\n";
    texte += "🌡️ Temp: " + d.temperature + " °C\n";
    texte += "📈 Niveau: " + d.niveau + " %\n";
    texte += "⏱️ " + new Date().toLocaleTimeString();
} else {
    texte = "🚨 ALERTE DESSALEMENT\n";
    texte += "━━━━━━━━━━━━━━━━\n";
    alarmes.forEach(function(a) { texte += a + "\n"; });
    texte += "━━━━━━━━━━━━━━━━\n";
    texte += "💧 Salinité: " + d.salinite + " ppm\n";
    texte += "📊 Débit: " + d.debit_feed + " m³/h\n";
    texte += "🌡️ Temp: " + d.temperature + " °C\n";
    texte += "📈 Niveau: " + d.niveau + " %\n";
    texte += "⏱️ " + new Date().toLocaleTimeString();
}

msg.payload = {
    chatId: parseInt(env.get("TELEGRAM_CHAT_ID") || "0"),
    type: "message",
    content: texte
};

// Also store alarm state for other nodes
flow.set("alarm_state", {
    niveau: niveau_alerte,
    count: alarmes.length,
    details: alarmes,
    etat: etat,
    timestamp: new Date().toTimeString().slice(0,8)
});

return msg;

// Route commands to appropriate handlers
var cmd = msg.payload.content;
var chatId = msg.payload.chatId;

msg.chatId = chatId;

if (cmd === "/start") {
    msg.route = "start";
    return [msg, null, null, null];
} else if (cmd === "/status") {
    msg.route = "status";
    return [null, msg, null, null];
} else if (cmd === "/demarrer") {
    msg.route = "demarrer";
    return [null, null, msg, null];
} else if (cmd === "/arreter") {
    msg.route = "arreter";
    return [null, null, null, msg];
} else {
    // Unknown command
    msg.payload = {
        chatId: chatId,
        type: "message",
        content: "❓ Commande inconnue. Utilisez:\n/start - Démarrer\n/status - État système\n/demarrer - Démarrer la pompe\n/arreter - Arrêter la pompe"
    };
    return [null, null, null, null];
}

msg.payload = {
