} else if (text === "/demarrer") {
    var cmdMsg = { payload: { cmd: "START", chatId: chatId } };
    var replyMsg = { payload: { chatId: chatId, type: "message", content: "🟢 Commande DÉMARRAGE envoyée au PLC", options: {} } };
