// Calcul du jour calendaire en heure Tunisie (UTC+1)
let now = new Date();
let tunis = new Date(now.toLocaleString('en-US', { timeZone: 'Africa/Tunis' }));
let year = tunis.getFullYear();
let month = String(tunis.getMonth() + 1).padStart(2, '0');
let day = String(tunis.getDate()).padStart(2, '0');

// Début du jour J à 00:00:00 heure Tunisie (UTC+1 = +01:00)
