let rows = msg.payload || [];
let chartDate = msg.chartDate || new Date().toLocaleDateString('fr-FR', { timeZone: 'Africa/Tunis' });
msg.chatId = msg.chatIdSaved || msg.chatId || msg.triggerChatId || "1132245782";

node.status({fill:'blue', shape:'ring', text: rows.length + ' points trouvés'});

// --- Heure actuelle en Tunisie ---
let now = new Date();
let tunisNow = new Date(now.toLocaleString('en-US', { timeZone: 'Africa/Tunis' }));
let currentHour = tunisNow.getHours();

// --- Labels fixes 0h → 23h ---
let labels = [];
for (let i = 0; i < 24; i++) { labels.push(i + 'h'); }

// --- Regroupement par heure (Tunisie) ---
let buckets = {};
rows.forEach(row => {
    let d = new Date(row.timestamp);
    let local = new Date(d.toLocaleString('en-US', { timeZone: 'Africa/Tunis' }));
    let key = local.getHours() + 'h';
    if (!buckets[key]) buckets[key] = [];
    buckets[key].push(parseFloat(row.value));
});

// --- Calcul MOYENNE par heure (heures futures = null) ---
let data = labels.map((k, index) => {
    if (index > currentHour) return null;                          // futur → vide
    if (!buckets[k] || buckets[k].length === 0) return null;      // pas de données
    let sum = buckets[k].reduce((a, b) => a + b, 0);
    return Math.round((sum / buckets[k].length) * 10) / 10;       // moyenne arrondie 1 décimale
});

// --- Comptage heures renseignées ---
let filledCount = data.filter(v => v !== null).length;
let subtitle = filledCount + '/24 heures avec données';
if (filledCount <= 2) {
    subtitle = '⚠️ Données insuffisantes (' + filledCount + ' heure(s)) — Vérifier MQTT/DB';
}

node.status({fill: filledCount > 2 ? 'green' : 'yellow', shape:'ring', text: subtitle});

msg.payload = {
    chart: {
        type: 'line',
        data: {
            labels: labels,
            datasets: [{
                label: 'MW Production',
                data: data,
                borderColor: '#2ecc71',
                backgroundColor: 'rgba(46, 204, 113, 0.12)',
                fill: true,
                tension: 0.3,
                pointRadius: data.map(v => v !== null ? 5 : 0),
                pointHoverRadius: 8,
                pointBorderColor: '#27ae60',
                pointBackgroundColor: '#2ecc71',
                pointBorderWidth: 2,
                spanGaps: false
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: true,
            plugins: {
                datalabels: {
                    display: true,
                    align: 'top',
                    anchor: 'end',
                    color: '#1a5c36',
                    font: { size: 6, weight: 'bold' },
                    formatter: (v) => v !== null ? v + ' MW' : ''
                }
            },
            scales: {
                xAxes: [{
                    ticks: { autoSkip: false, maxRotation: 45, minRotation: 45, fontSize: 11 },
                    scaleLabel: { display: true, labelString: 'Heure (Tunisie)', fontSize: 12, fontStyle: 'bold' }
                }],
                yAxes: [{
                    ticks: {
                        min: 0, max: 450, stepSize: 50,
                        callback: (v) => v + ' MW',
                        fontSize: 11
                    },
                    scaleLabel: { display: true, labelString: 'MW', fontSize: 12, fontStyle: 'bold' }
                }]
            },
            title: {
                display: true,
                text: ['⚡ MW Production - Sousse D', chartDate, subtitle],
                fontSize: 14,
                fontStyle: 'bold',
                fontColor: '#1a5c36',
                padding: 12
            },
